    public static class ReşatNuriGüntekin
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://tr.wikiquote.org/wiki/Reşat_Nuri_Güntekin", Text = "İnsan yaşadığı yerlerde beraber bulunduğu insanlara görünmez ince tellerle bağlanırmış; ayrılık vaktinde bu bağlar gerilmeye, kopan keman telleri gibi acı sesler çıkarmaya başlar, hep birinin gönlümüzden kopup ayrılması bir ayrı sızı uyandırırmış. Bunu yazan şair ne kadar haklıymış!", Author = "Reşat Nuri Güntekin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Reşat_Nuri_Güntekin", Text = "Sen, kurşunla vurulanları hiç işitmedin mi, be hemşireceğim? Bazıları, vurulduklarının fakında bile olamazlar, üç beş adım koşarlar, kaçıp kurtuluyoruz sanırlar. Yara sıcakken acımaz, hemşireceğim. Hele bir kere soğumaya başlasın. Sen bak, seyret o kızcağız nasıl yanıp yakılacak?", Author = "Reşat Nuri Güntekin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Reşat_Nuri_Güntekin", Text = "Sevmek denen şeyin rolü bu kadar insanı yakıp titretecek bir şey olursa kendisi kim bilir neydi?", Author = "Reşat Nuri Güntekin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Reşat_Nuri_Güntekin", Text = "İnsan için, her şeyi söylerler... Ne çıkar? Elverir ki, vicdanı temiz olsun...", Author = "Reşat Nuri Güntekin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Reşat_Nuri_Güntekin", Text = "Sevdayı dudaklardan öteye bırakmamak, zehir gibi kalbe inmesine meydan vermemek.", Author = "Reşat Nuri Güntekin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Reşat_Nuri_Güntekin", Text = "Gözden düşen, fikirlerinden korkulan mabeyin adamlarını buraya mutasarrıf gönderirlerdi.", Author = "Reşat Nuri Güntekin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Reşat_Nuri_Güntekin", Text = "İnsan olmadıktan sonra ibadet etmiş neye yarar ki?", Author = "Reşat Nuri Güntekin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Reşat_Nuri_Güntekin", Text = "Vücudumun çirkin kabuğu altında sevgi ile, rikkat ile dolup taşan zengin bir kalbim varmış... Ne çare ki kimse beni sevmemiş, kalbimdeki o taşkın memba kendi kendine kurumuş. Sevgilerim nefrete, kine, bedhahlığa kalbolmuş...", Author = "Reşat Nuri Güntekin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Reşat_Nuri_Güntekin", Text = "Saadeti saklamak, acıyı saklamaktan çok daha güç...", Author = "Reşat Nuri Güntekin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Reşat_Nuri_Güntekin", Text = "Kafaları değiştirmeden idareyi değiştirmek öyle pek tamah edilecek bir netice vermiyor.", Author = "Reşat Nuri Güntekin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Reşat_Nuri_Güntekin", Text = "İnkılap denilen şey bir günde olmuyor.", Author = "Reşat Nuri Güntekin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Reşat_Nuri_Güntekin", Text = "Acımak... Ben insan ruhlarındaki derinliğin ancak, onunla ölçülebileceğine kaniim. Evet, dibi görünmeyen kuyulara atılan taş nasıl çıkardığı sesle onların derinliğini gösterirse başkalarının elemi de bizim yüreklerimize düştüğü zaman çıkardığı sesle bize kendimizi, insanlığımızın derecesini öğretir...", Author = "Reşat Nuri Güntekin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Reşat_Nuri_Güntekin", Text = "İnsanlar hiçbir vakit ıstırap çektikleri zamandaki kadar güzel olmuyorlar.", Author = "Reşat Nuri Güntekin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Reşat_Nuri_Güntekin", Text = "Memleketin ancak okuyup yazmakla kurtulacağına inananlardanım.", Author = "Reşat Nuri Güntekin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Reşat_Nuri_Güntekin", Text = "Kendi köşesinde çalışan, belki de kendi halinden, hayatından memnun olan insanlarda olmayacak birtakım arzular ve isyanlar uyandırmak doğru mu?", Author = "Reşat Nuri Güntekin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Reşat_Nuri_Güntekin", Text = "İnsan, mesela ibadet, yahut çalgı ile meşgul olmakla; zerzevat, çiçek, yahut çocuk yetiştirmekte de bir teselli bulabilir. Ancak bunun için de hiç olmazsa yaşayacak kadar bir para lazımdır.", Author = "Reşat Nuri Güntekin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Reşat_Nuri_Güntekin", Text = "Çiçek meraklısısınız; fakat biraz paranız yok değil mi? Ne kadar uğraşsanız topraktan istediğiniz renkte, kokuda bir çiçek alamayacağınıza emin olun...", Author = "Reşat Nuri Güntekin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Reşat_Nuri_Güntekin", Text = "Anlaşılan çocuklarla fincan takımları arasında pek fark yoktu. Kırıla kırıla bir tek kaldıkları gibi işe yaramaz oluyorlar, bir köşeye atılıyorlardı.", Author = "Reşat Nuri Güntekin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Reşat_Nuri_Güntekin", Text = "Sandıklar dolusu kitap okuyorum senelerce etrafımdakilerle ve kendi kendimle çarpışıyorum, birçok sevgilerimi, meyillerimi, ümitlerimi, kan ve göz yaşlarına bakmadan boğazlıyorum. Bütün bu didinmeler niçin? Kafamı rüya ve esatirden temizlemek, istiklallerin en güç elde edileni olan fikir istiklâline erişmek için değil mi?", Author = "Reşat Nuri Güntekin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Reşat_Nuri_Güntekin", Text = "Nihayet, gece, içinden ne renkte bir sabah çıkacağı bilinmediği için ümide de hayli pay bırakan bir kapalı kutudur.", Author = "Reşat Nuri Güntekin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Reşat_Nuri_Güntekin", Text = "İnsanın en miskini sıkıyı görünce düldül oluyor Yarabbi!", Author = "Reşat Nuri Güntekin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Reşat_Nuri_Güntekin", Text = "Muhtaç olduğun kudret damarlarındaki kandadır.", Author = "Reşat Nuri Güntekin" },
        };
